#!/usr/bin/env python3
"""
Round 168m (culprits), 4 October 2026. Needs round 167m.

Mother Earth: a magical pastel look; a sharp, lightly tinted photograph close in.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 168m (4 October)\n\nNeeds round 167m. No tiles patch. app.js?v= bumped to 1007.\n\n- Owner on 167m: the map had gone grey; the wish was a magical, girly,\n  Never Never Land look. And very blurry at the highest zooms: those should\n  be the normal satellite photograph, tweaked slightly to the theme, with no\n  blurring.\n- Palette (MOTHER): a pastel dream. Plants deep jade to sea-glass mint;\n  bare ground, rock and desert rose-quartz and blush, lit to pearl;\n  turquoise lagoon water and shallows; pearl-pink snow; a rose mist on high\n  ground (haze); pink-cream hillshade light, soft blue shadows; towns and\n  roads soft rose-greys; names pearl-pink on a deep blue halo. Purple still\n  only in the sky. No brown, grey, orange, yellow or neon (tests).\n- Close in: the painting (from 10 m Sentinel-2, enlarged past zoom 14) gives\n  way to Esri's photograph from zoom 13.5, fully by 14.5 (was 15.5 to\n  16.5); the photograph is asked for to zoom 19 (was 18) and only lightly\n  tinted (photoGrade 0.22, was 0.5), colour only, nothing blurred.\n- The (i) note's first paragraph follows.\n- Checked in Chromium on sample tiles: world view (painted) and a zoom-17\n  city photograph (graded). Not seen live.\n"]
DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round168m: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 167m" not in h.read_text(encoding="utf-8"):
        sys.exit("round168m: round 167m must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round168m: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", "map/index.html", check=False)
            sys.exit("round168m: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round168m: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
